# Toy SS7 firewall: FS.11-style categories on synthetic messages
HOME = "23415"   # our MCC+MNC
CAT1 = {"AnyTimeInterrogation", "SendIMSI", "SendRoutingInfo"}
CAT2 = {"ProvideSubscriberInfo", "InsertSubscriberData"}
CAT3 = {"UpdateLocation", "SendAuthenticationInfo"}
MAX_KMH = 1000   # faster than any airliner
last = {"234150000000001": ((51.5, -0.1), 0.0)}

def km(a, b):   # rough, toy only
    return ((a[0]-b[0])**2 + ((a[1]-b[1])*0.62)**2) ** 0.5 * 111

def check(m):
    op, src, imsi = m["op"], m["src"], m["imsi"]
    if src == HOME:
        return "allow (internal)"
    if op in CAT1:
        return "block cat1: never valid between networks"
    if op in CAT2 and not imsi.startswith(src):
        return "block cat2: only the subscriber's home may send it"
    if op in CAT3 and imsi in last:
        pos, t = last[imsi]
        kmh = km(pos, m["pos"]) / max(m["h"] - t, 0.01)
        if kmh > MAX_KMH:
            return f"block cat3: implies {kmh:,.0f} km/h"
        last[imsi] = (m["pos"], m["h"])
    return "allow"

me, guest = "234150000000001", "208010000000042"
for m in [
    {"op": "AnyTimeInterrogation", "src": "99901", "imsi": me},
    {"op": "ProvideSubscriberInfo", "src": "99901", "imsi": me},
    {"op": "ProvideSubscriberInfo", "src": "20801", "imsi": guest},
    {"op": "UpdateLocation", "src": "99901", "imsi": me, "pos": (-6.2, 106.8), "h": 0.5},
    {"op": "UpdateLocation", "src": "20801", "imsi": me, "pos": (48.9, 2.4), "h": 3.0},
]:
    print(f'{m["op"]:21} from {m["src"]}: {check(m)}')

