# Flag suspicious cells in UE measurement reports (ideas from TS 33.501 Annex E)
DEPLOYED = {   # cell id: (frequency channel, expected strongest dBm nearby)
    1101: (632628, -75), 1102: (632628, -80), 1201: (643296, -85)}

reports = [    # (reporting UE, cell id, channel, measured dBm)
    ("ue1", 1101, 632628, -78), ("ue2", 1102, 632628, -83),
    ("ue3", 1101, 632628, -48), ("ue4", 1101, 632628, -47),   # far too strong
    ("ue5", 1999, 632628, -60), ("ue6", 1999, 632628, -62),   # unknown cell
    ("ue7", 1201, 650000, -70), ("ue8", 1201, 650000, -71),   # wrong channel
    ("ue9", 1102, 632628, -40),                               # one odd report
]

def flags(cell, chan, dbm):
    if cell not in DEPLOYED:
        return "cell id not in our deployment"
    exp_chan, exp_dbm = DEPLOYED[cell]
    if chan != exp_chan:
        return "cell on a channel we never configured"
    if dbm > exp_dbm + 20:
        return "signal 20+ dB stronger than planned"
    return None

seen = {}
for ue, cell, chan, dbm in reports:
    why = flags(cell, chan, dbm)
    if why:
        seen.setdefault((cell, why), set()).add(ue)
for (cell, why), ues in sorted(seen.items()):
    verdict = "ALERT" if len(ues) >= 2 else "watch (single UE, could be a rogue report)"
    print(f"cell {cell}: {why}; {len(ues)} UE(s), {verdict}")

# Parse an eSIM Activation Code (GSMA SGP.22 section 4.1) and review how it is issued
def parse_ac(ac: str):
    parts = ac.split("$")
    if parts[0] != "1":
        raise ValueError("AC_Format must be 1")
    return {"smdp": parts[1], "matching_id": parts[2],
            "cc_required": len(parts) > 4 and parts[4] == "1"}

def review(info, eid_bound, channel, after_sim_change):
    issues = []
    if not info["cc_required"] and not eid_bound:
        issues.append("no Confirmation Code, no EID binding: any holder can download it")
    if channel == "email":
        issues.append("code sent to a mailbox an attacker may already control")
    if after_sim_change:
        issues.append("issued right after a number or SIM change: handle as a SIM swap")
    return issues or ["ok"]

orders = [("1$SMDP.EXAMPLE.COM$04386-AGYFT-A74Y8-3F815", False, "email", True),
          ("1$SMDP.EXAMPLE.COM$04386-AGYFT-A74Y8-3F815$$1", True, "in-app", False)]
for ac, eid_bound, channel, recent in orders:
    info = parse_ac(ac)
    print(info["smdp"], info["matching_id"], "cc_required =", info["cc_required"])
    for issue in review(info, eid_bound, channel, recent):
        print("  -", issue)

# Toy SIM-swap risk score for a bank about to send an SMS code or move money
WEIGHTS = {
    "sim_changed_72h": 40,      # e.g. from an operator SIM-swap check API
    "number_ported_30d": 30,
    "new_device": 15,
    "new_payee_or_reset": 20,   # adding a payee, password or phone change
    "login_country_changed": 10,
}

def score(signals):
    return sum(w for k, w in WEIGHTS.items() if signals.get(k))

def decide(s):
    if s >= 60:
        return "hold: no SMS, verify with a passkey or an out-of-band call to known details"
    if s >= 30:
        return "step up: require the passkey, never SMS"
    return "proceed"

cases = {
    "routine login":           {},
    "new phone, same SIM":     {"new_device": True},
    "SIM changed yesterday":   {"sim_changed_72h": True},
    "swap then payee + reset": {"sim_changed_72h": True, "new_device": True,
                                "new_payee_or_reset": True},
}
for name, sig in cases.items():
    s = score(sig)
    print(f"{name:24} score {s:3}  {decide(s)}")

# Audit: compare intercept tasks found on network elements with the warrant master list
from datetime import date
TODAY = date(2026, 11, 23)
warrants = {   # warrant id: (target number, expires, approved delivery point)
    "W-101": ("+44700900001", date(2026, 12, 31), "LEMF-A"),
    "W-102": ("+44700900002", date(2026, 11, 1), "LEMF-A"),
}
# what each switch / POI reports when audited directly, not through the LI GUI
tasks = [
    ("msc-1", "+44700900001", "LEMF-A", "W-101"),
    ("msc-1", "+44700900002", "LEMF-A", "W-102"),
    ("msc-2", "+44700900777", "+44700555123", None),   # no warrant, odd destination
]

for poi, target, dest, wid in tasks:
    w = warrants.get(wid)
    if w is None:
        print(f"CRITICAL {poi}: tap on {target} to {dest} has no warrant")
    elif w[0] != target:
        print(f"CRITICAL {poi}: {wid} covers {w[0]}, not {target}")
    elif w[1] < TODAY:
        print(f"HIGH {poi}: {wid} expired {w[1]}, tap still active")
    elif dest != w[2]:
        print(f"CRITICAL {poi}: {wid} delivers to {dest}, approved {w[2]}")
    else:
        print(f"ok {poi}: {wid}")

# Guard in front of a terminal-management system: limit the blast radius of commands
DESTRUCTIVE = {"flash_write", "factory_reset", "firmware_push"}
OPS_HOSTS = {"10.20.0.11", "10.20.0.12"}     # jump hosts in the ops segment
MAX_UNATTENDED = 50                          # devices per destructive job without review

def gate(job):
    reasons = []
    if job["src"] not in OPS_HOSTS:
        reasons.append(f"issued from {job['src']}, not an ops jump host")
    if job["cmd"] in DESTRUCTIVE and job["targets"] > MAX_UNATTENDED:
        if len(set(job["approvers"])) < 2:
            reasons.append(f"{job['targets']:,} devices needs two approvers")
        if not job.get("change_ticket"):
            reasons.append("no change ticket")
    return ("BLOCK: " + "; ".join(reasons)) if reasons else "run in waves of 50, watch health"

jobs = [
    {"cmd": "config_push", "targets": 1200, "src": "10.20.0.11", "approvers": ["ana"]},
    {"cmd": "firmware_push", "targets": 8000, "src": "10.20.0.12",
     "approvers": ["ana", "raj"], "change_ticket": "CHG-4411"},
    {"cmd": "flash_write", "targets": 40000, "src": "172.16.9.4", "approvers": ["svc-vpn"]},
]
for j in jobs:
    print(f"{j['cmd']:13} x{j['targets']:>6,}: {gate(j)}")
